let d = {};
try {
  d = JSON.parse($json.choices?.[0]?.message?.content ?? '{}');
} catch (e) { d = {}; }

return {
  reply: d.reply ?? null,
  drafted_at: new Date().toISOString(),
  is_unsure: d.is_unsure === true || !d.reply,
  used_article_ids: Array.isArray(d.used_article_ids) ? d.used_article_ids.filter(Number.isInteger) : [],
  model: $json.model ?? null,
  input_tokens: $json.usage?.prompt_tokens ?? null,
  output_tokens: $json.usage?.completion_tokens ?? null,
};

const c = $('Save classification').item.json;
const reasons = [];

if (!c.is_valid) reasons.push('invalid_classification');
if (c.confidence !== null && Number(c.confidence) < 0.7) reasons.push('confidence<0.7');
if (['urgent', 'high'].includes(c.priority)) reasons.push('priority=' + c.priority);
if ($json.is_unsure) reasons.push('model_unsure');

return {
  ...$json,
  ticket_id: c.ticket_id,
  classification_id: c.id,
  routed_to: reasons.length ? 'human_queue' : 'draft_review',
  routing_reason: reasons.join(', ') || 'confident, normal priority',
};

parameters.jsonBody:
={{ JSON.stringify({
  model: "openai/gpt-oss-120b",
  temperature: 0,
  messages: [
    { role: "system", content: `You triage support tickets for a marketing data platform that pulls data from ad platforms (Meta Ads, Google Ads, GA4, TikTok) into a warehouse and dashboards. Classify the ticket.

Categories:
- data_discrepancy: numbers differ from the source platform, or data is missing or delayed
- connector_auth: connecting, adding, reauthorizing or giving access to data sources; failures caused by login, OAuth, expired tokens or permissions. Use this even when it is phrased as a how-to question.
- api_error: extraction or API failures, rate limits, timeouts, error codes, schema changes
- billing: invoices, payments, plan or pricing
- other: anything else

Priority is about impact, not wording. Ask: is the customer's data still flowing and correct, and will the problem fix itself?
- urgent: data stopped or is wrong across many accounts or the whole workspace, OR the customer states a hard deadline within hours.
- high: data has stopped flowing or is clearly wrong for an account and will not recover on its own. Examples: a connector disconnected or failing auth on every run, extractions erroring on every run since a point in time, errors returned by our API, a schema or field change breaking their pipeline, duplicated or inflated data, data no longer updating. Also money taken incorrectly, such as a double charge.
- normal: the customer has a problem but data mostly still flows. Examples: a number mismatch on one report or campaign, timeouts or rate limits on one heavy job, a permission error on a single property, a reconnect prompt where they ask what to do, plan or pricing questions, compliance or data deletion requests.
- low: nothing is broken. Questions about how things work or expected platform behaviour, how-to questions, feature requests, admin paperwork such as invoice corrections or tax forms, thank-you notes.

When unsure between two priorities, pick the higher one. Missing a broken pipeline is worse than an extra human review.

Confidence: 0 to 1, how sure you are about the category. Go below 0.6 if the ticket is vague or fits several categories. Reasoning: one short sentence.` },
    { role: "user", content: "Subject: " + $('Webhook').item.json.body.subject + "\n\n" + $('Webhook').item.json.body.body }
  ],
  response_format: {
    type: "json_schema",
    json_schema: {
      name: "ticket_classification",
      strict: true,
      schema: {
        type: "object",
        properties: {
          category: { type: "string", enum: ["data_discrepancy","connector_auth","api_error","billing","other"] },
          priority: { type: "string", enum: ["urgent","high","normal","low"] },
          confidence: { type: "number" },
          reasoning: { type: "string" }
        },
        required: ["category","priority","confidence","reasoning"],
        additionalProperties: false
      }
    }
  }
}) }}
